import{_ as i,o as s,c as e,ag as t}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"构建与开发","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/development.md","filePath":"shitbot/development.md"}'),l={name:"shitbot/development.md"};function n(p,a,h,o,d,r){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="构建与开发" tabindex="-1">构建与开发 <a class="header-anchor" href="#构建与开发" aria-label="Permalink to &quot;构建与开发&quot;">​</a></h1><p>本页面面向需要从源码构建或修改 ShitBot 的开发者。普通服主应从 <a href="https://github.com/hutuyee/ShitBot/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载发布 JAR。</p><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><ul><li>JDK 21；</li><li>Maven 3.8 或更高版本；</li><li>可以访问 Maven Central、Spigot、BungeeCord、Velocity 和 Nukkit-MOT 依赖仓库。</li></ul><p>整个聚合工程由 JDK 21 构建，各模块输出：</p><table tabindex="0"><thead><tr><th>模块</th><th>字节码目标</th></tr></thead><tbody><tr><td>ShitBotApi</td><td>Java 8</td></tr><tr><td>ShitBotCore</td><td>Java 8</td></tr><tr><td>ShitBotRenderer</td><td>Java 8</td></tr><tr><td>ShitBotSpigot</td><td>Java 8</td></tr><tr><td>ShitBotBungee</td><td>Java 8</td></tr><tr><td>ShitBotVelocity</td><td>Java 21</td></tr><tr><td>ShitBotNukkit</td><td>Java 17</td></tr></tbody></table><h2 id="构建全部平台" tabindex="-1">构建全部平台 <a class="header-anchor" href="#构建全部平台" aria-label="Permalink to &quot;构建全部平台&quot;">​</a></h2><p>在仓库根目录执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package</span></span></code></pre></div><p>版本由 <code>.mvn/maven.config</code> 中的 <code>revision</code> 属性提供。需要临时指定版本时：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Drevision</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SNAPSHOT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package</span></span></code></pre></div><h2 id="构建单个平台" tabindex="-1">构建单个平台 <a class="header-anchor" href="#构建单个平台" aria-label="Permalink to &quot;构建单个平台&quot;">​</a></h2><p>使用 <code>-am</code> 同时构建依赖的 ShitBotApi 与 ShitBotCore：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotSpigot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotBungee </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotVelocity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotNukkit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span></code></pre></div><p>最终插件 JAR 位于对应模块的 <code>target/</code>。不要发布 <code>original-*.jar</code>、sources、javadoc 或 test JAR。</p><h2 id="模块结构" tabindex="-1">模块结构 <a class="header-anchor" href="#模块结构" aria-label="Permalink to &quot;模块结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShitBot/</span></span>
<span class="line"><span>├─ ShitBotApi/        # 绑定、白名单、图片 API 与渲染 SPI，独立发布供开发者依赖</span></span>
<span class="line"><span>├─ ShitBotCore/       # OneBot、数据库、绑定、图片、更新和共享业务逻辑</span></span>
<span class="line"><span>├─ ShitBotRenderer/   # 单独发布并按需下载的高级 Java2D 场景渲染器与编辑器</span></span>
<span class="line"><span>├─ ShitBotSpigot/     # Bukkit、Paper、Folia 与后端命令监听</span></span>
<span class="line"><span>├─ ShitBotBungee/     # BungeeCord 平台入口</span></span>
<span class="line"><span>├─ ShitBotVelocity/   # Velocity 平台入口</span></span>
<span class="line"><span>├─ ShitBotNukkit/     # Nukkit-MOT 平台入口</span></span>
<span class="line"><span>├─ PictureBridge/     # 独立客户端模组的 Git 子模块</span></span>
<span class="line"><span>├─ docs/              # 项目文档</span></span>
<span class="line"><span>└─ pom.xml            # Maven 聚合工程</span></span></code></pre></div><p>平台模块依赖 ShitBotCore，并将运行所需的共享依赖重定位到最终 JAR。平台 API 依赖以 provided 范围使用，不应打包进发布 JAR。<code>ShitBotRenderer</code> 不得成为平台模块依赖；它通过 <code>ShitBotApi</code> 的 SPI 在运行时隔离加载，否则会破坏默认插件的体积边界和按需下载语义。</p><h2 id="配置资源" tabindex="-1">配置资源 <a class="header-anchor" href="#配置资源" aria-label="Permalink to &quot;配置资源&quot;">​</a></h2><p>各平台默认配置位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShitBotSpigot/src/main/resources/</span></span>
<span class="line"><span>ShitBotBungee/src/main/resources/</span></span>
<span class="line"><span>ShitBotVelocity/src/main/resources/</span></span>
<span class="line"><span>ShitBotNukkit/src/main/resources/</span></span></code></pre></div><p>修改配置结构时，应同步检查：</p><ul><li>四个平台的 <code>config.yml</code>；</li><li>平台适用的 <code>commands.yml</code>；</li><li>Core 中共享的 <code>lang/zh_CN.yml</code> 与 <code>lang/en_US.yml</code>；</li><li>Core 中共享的 <code>templates/default.yml</code>；</li><li>配置加载器与默认值；</li><li>重载流程；</li><li>本文档中引用的配置示例。</li></ul><p>Nukkit-MOT 不包含代理—后端传输配置，其他平台的 <code>commands.yml</code> 共享同一配置结构。</p><h2 id="picturebridge-子模块" tabindex="-1">PictureBridge 子模块 <a class="header-anchor" href="#picturebridge-子模块" aria-label="Permalink to &quot;PictureBridge 子模块&quot;">​</a></h2><p>PictureBridge 是独立仓库和独立构建，不参与 ShitBot Maven 聚合工程。只修改服务端插件时，不需要构建 PictureBridge。</p><p>需要同时开发客户端模组时，克隆仓库后初始化子模块：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git submodule update </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">init </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">recursive</span></span></code></pre></div><p>PictureBridge 的构建说明见其独立仓库文档。</p><h2 id="ci-与-release" tabindex="-1">CI 与 Release <a class="header-anchor" href="#ci-与-release" aria-label="Permalink to &quot;CI 与 Release&quot;">​</a></h2><p>GitHub Actions 在 push、pull request 和手动触发时：</p><ol><li>使用 JDK 21 执行 <code>mvn clean package</code>；</li><li>收集四个平台 JAR、一个 <code>ShitBotApi</code> JAR 和一个独立 <code>ShitBotRenderer</code> JAR；</li><li>为各个 JAR 生成 SHA-256 文件；</li><li>上传工作流 Artifact。</li></ol><p>发布 GitHub Release 时，工作流还会：</p><ol><li>使用仓库 Secret 中的 RSA 私钥签署四个平台 JAR、公开 API JAR 和可选渲染器 JAR；</li><li>检查六个 JAR、六个 checksum 和六个签名；</li><li>将 JAR、<code>.sha256</code> 和 <code>.sig</code> 上传到 Release。</li></ol><p>签名密钥管理见<a href="./updating.html">升级与自动更新</a>。</p><h2 id="发布前文档" tabindex="-1">发布前文档 <a class="header-anchor" href="#发布前文档" aria-label="Permalink to &quot;发布前文档&quot;">​</a></h2><p>发布包含配置变更的版本时，应在 Release Notes 明确说明：</p><ul><li>是否需要重新生成或补充 <code>config.yml</code>；</li><li>是否需要同步更新代理与后端；</li><li>数据库是否发生迁移；</li><li>Java 或平台最低版本是否变化；</li><li>是否新增权限、端口或外部网络依赖。</li></ul>`,38)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
